import type { AudioTrackSummary } from '../../api/contentSchemas';
import { captureAccountOperation, isAccountOperationCurrent, type AccountOperationGuard } from '../../api/accountEpoch';
import {
  playbackActivityTarget,
  playerStore,
  RoomPlaybackActiveError,
  type PlaybackActivityEvent,
  type PlayerQueueItem
} from '../../player';

let latestPlaybackLaunch = 0;

/** Adapts the compatibility-named public track DTO to the MediaTrack queue contract. */
export const queueItemFromTrack = (track: AudioTrackSummary): PlayerQueueItem => ({
  id: track.id,
  title: track.title,
  artworkUrl: track.artworkUrl,
  artistNames: track.artistNames,
  displayByline: track.displayByline,
  mediaType: track.mediaType,
  streamUrl: track.streamUrl
});

const recordAfterPlaybackStarts = (
  guard: AccountOperationGuard | undefined,
  event: PlaybackActivityEvent,
  launchGeneration: number,
  expectedTrackId: string
) => {
  const snapshot = playerStore.getSnapshot();
  if (!guard || !isAccountOperationCurrent(guard)
    || launchGeneration !== latestPlaybackLaunch
    || snapshot.status !== 'playing'
    || snapshot.currentItem?.id !== expectedTrackId) return;
  const target = playbackActivityTarget(event);
  if (!target) return;
  void import('./recordPlaybackHistory').then(({ recordPlaybackHistory }) => {
    return recordPlaybackHistory(target, guard.viewerId, guard);
  }).catch(() => {
    // Activity history is best-effort and never interrupts public playback.
  });
};

/** Launches one MediaTrack outside an Album queue and records only that item. */
export const launchStandalonePlayback = async (
  track: AudioTrackSummary,
  viewerId?: string | null
) => {
  const launchGeneration = ++latestPlaybackLaunch;
  const guard = viewerId ? captureAccountOperation(viewerId) : undefined;
  await playerStore.launchStandalone(queueItemFromTrack(track));
  recordAfterPlaybackStarts(
    guard,
    { type: 'standaloneTrack', trackId: track.id },
    launchGeneration,
    track.id
  );
};

/** Starts an Album queue for an already-captured account guard and launch generation. */
const launchAlbumQueue = async (
  albumId: string,
  tracks: AudioTrackSummary[],
  guard: AccountOperationGuard | undefined,
  launchGeneration: number,
  requestedTrackId?: string
) => {
  const requestedIndex = requestedTrackId
    ? tracks.findIndex((track) => track.id === requestedTrackId)
    : -1;
  const initialIndex = requestedIndex >= 0 ? requestedIndex : 0;
  await playerStore.launchAlbumQueue(tracks.map(queueItemFromTrack), initialIndex);
  recordAfterPlaybackStarts(
    guard,
    requestedIndex >= 0
      ? { type: 'explicitAlbumTrack', trackId: tracks[initialIndex].id }
      : { type: 'albumPlay', albumId },
    launchGeneration,
    tracks[initialIndex].id
  );
};

/** Launches the complete playable Album queue from its first or explicitly chosen track. */
export const launchAlbumPlayback = async (
  albumId: string,
  tracks: AudioTrackSummary[],
  viewerId?: string | null,
  requestedTrackId?: string
) => {
  if (tracks.length === 0) return;
  const launchGeneration = ++latestPlaybackLaunch;
  const guard = viewerId ? captureAccountOperation(viewerId) : undefined;
  await launchAlbumQueue(albumId, tracks, guard, launchGeneration, requestedTrackId);
};

/** Outcome of a deferred Album launch; a failed or timed-out load rejects instead. */
export type DeferredAlbumLaunchResult = 'started' | 'empty' | 'superseded' | 'roomActive';

/**
 * Browsers keep transient user activation for about five seconds, so a load slower than this
 * would start playback the listener no longer expects (and might be refused as autoplay).
 */
export const deferredAlbumLoadLimitMs = 5_000;

/** Rejects a deferred Album load that outlives the gesture's user-intent window. */
export class DeferredAlbumLoadTimeoutError extends Error {
  constructor() {
    super('The Album did not load within the playback intent window.');
    this.name = 'DeferredAlbumLoadTimeoutError';
  }
}

let latestDeferredAlbumIntent = 0;

const withinIntentWindow = <T>(load: Promise<T>) => new Promise<T>((resolve, reject) => {
  const timer = setTimeout(() => reject(new DeferredAlbumLoadTimeoutError()), deferredAlbumLoadLimitMs);
  load.then(
    (value) => { clearTimeout(timer); resolve(value); },
    (error: unknown) => { clearTimeout(timer); reject(error); }
  );
});

/**
 * Loads an Album's canonical ready-only queue for a card-level Play action, then starts it with
 * the same Album Play policy. The gesture only observes the launch generation; it claims one
 * just before starting, so an abandoned load never cancels an earlier launch's activity. A newer
 * launch, a newer card gesture, or an account change during the load abandons this one.
 */
export const launchAlbumPlaybackAfterLoad = async (
  albumId: string,
  loadTracks: () => Promise<AudioTrackSummary[]>,
  viewerId?: string | null
): Promise<DeferredAlbumLaunchResult> => {
  const intent = ++latestDeferredAlbumIntent;
  const observedLaunch = latestPlaybackLaunch;
  // Signed-out gestures are fenced by the account epoch too; only signed-in ones record activity.
  const fence = captureAccountOperation(viewerId ?? '');
  const guard = viewerId ? fence : undefined;
  const isSuperseded = () => intent !== latestDeferredAlbumIntent
    || observedLaunch !== latestPlaybackLaunch
    || !isAccountOperationCurrent(fence);

  let tracks: AudioTrackSummary[];
  try {
    tracks = await withinIntentWindow(loadTracks());
  } catch (error) {
    // A listener who already chose something else is not told that this older choice failed.
    if (isSuperseded()) return 'superseded';
    throw error;
  }
  if (isSuperseded()) return 'superseded';
  if (tracks.length === 0) return 'empty';
  const launchGeneration = ++latestPlaybackLaunch;
  try {
    await launchAlbumQueue(albumId, tracks, guard, launchGeneration);
  } catch (error) {
    if (error instanceof RoomPlaybackActiveError) return 'roomActive';
    throw error;
  }
  return 'started';
};

/** Launches a ready-only Playlist snapshot and records only its explicit start track. */
export const launchPlaylistPlayback = async (
  tracks: AudioTrackSummary[],
  viewerId?: string | null,
  requestedTrackId?: string
) => {
  if (tracks.length === 0) return;
  const requestedIndex = requestedTrackId
    ? tracks.findIndex((track) => track.id === requestedTrackId)
    : -1;
  const initialIndex = requestedIndex >= 0 ? requestedIndex : 0;
  const launchGeneration = ++latestPlaybackLaunch;
  const guard = viewerId ? captureAccountOperation(viewerId) : undefined;
  await playerStore.launchQueue(tracks.map(queueItemFromTrack), initialIndex);
  recordAfterPlaybackStarts(
    guard,
    { type: 'playlistTrack', trackId: tracks[initialIndex].id },
    launchGeneration,
    tracks[initialIndex].id
  );
};
